pub fn request_id(incoming: Option<&str>, fallback: &str) -> String {
    match incoming {
        Some(v)
            if !v.is_empty()
                && v.len() <= 64
                && v.bytes().all(|b| {
                    b.is_ascii_alphanumeric() || b == b'-' || b == b'_'
                }) =>
        {
            v.to_owned()
        }
        _ => fallback.to_owned(),
    }
}

fn main() {
    assert_eq!(
        request_id(Some("req_42-A"), "generated"),
        "req_42-A",
        "case 1"
    );
    assert_eq!(request_id(None, "generated"), "generated", "case 2");
    assert_eq!(
        request_id(
            Some(
                "evil
record"
            ),
            "new"
        ),
        "new",
        "case 3"
    );
    assert_eq!(request_id(Some("🦀"), "new"), "new", "case 4");
    assert_eq!(
        request_id(Some(&"a".repeat(65)), "new"),
        "new",
        "case 5"
    );
    assert_eq!(request_id(Some(""), "new"), "new", "case 6");
    println!("worked example passed");
}

